1	#!/usr/bin/env bun
2	/**
3	 * manage_dispatch_loop.ts — decide whether the agent chain has gone on long
4	 * enough to stop and ask a person.
5	 *
6	 * The I/O half. Every decision is in `domain/work/dispatch-chain.ts`, which explains
7	 * why this counts comments instead of keeping a counter -- briefly: the counter it
8	 * used to keep could not reach 1, because the reset fired on any new event and
9	 * every run posts a result comment.
10	 *
11	 * Usage:
12	 *   manage_dispatch_loop.ts --number 123 [--repo owner/name]
13	 *
14	 * Writes `auto_dispatch_count=N`, `loop_limit_reached=true|false`,
15	 * `handoff_limit=N`, `runs_without_change=N` and `stop_reason=<sentence>` to
16	 * $GITHUB_OUTPUT. The first two names are unchanged so the workflow's guards and
17	 * `decide_turn_ending`'s input keep working.
18	 *
19	 * `loop_limit_reached` now covers two limits: consecutive handoffs and
20	 * consecutive runs that changed nothing. One guard, because the workflow's
21	 * response to both is the same -- withhold the handoff and tell a person -- and
22	 * `stop_reason` is what makes the message say which.
23	 *
24	 * No longer takes `--session`. Nothing is written back: the tally is derived, so
25	 * there is nothing to persist and nothing for a stale session to contradict. Old
26	 * sessions still carry `metadata.github_context.auto_dispatch_count`; it is dead
27	 * and nothing reads it.
28	 */
29	import { appendFileSync } from "node:fs";
30	import { parseArgs } from "node:util";
31	import { handoffsSincePerson, resolveHandoffLimit, type ChainComment } from "../../domain/work/dispatch-chain.ts";
32	import { resolveNoProgressLimit, runsWithoutChange, stopReason } from "../../domain/work/progress.ts";
33	import { getHandoffLimit, getNoProgressLimit } from "../../adapters/runner/config.ts";
34	import { listComments } from "../../adapters/github/thread.ts";
35	import { CHANGED_TAG, isResultComment } from "../../adapters/github/tags.ts";
36	import { defineScript } from "./lib/script-ref.ts";
37	
38	export interface ManageDispatchLoopArgs {
39	  number: string | number;
40	  repo?: string;
41	}
42	
43	export const ref = defineScript<ManageDispatchLoopArgs>(import.meta.url);
44	
45	/**
46	 * The target's comments, oldest first, reduced to what the decision reads.
47	 *
48	 * `--paginate` (inside the shared `listComments`) because a long-running issue passes
49	 * 100 comments, and the tally is read from the END of the list: a truncated read would
50	 * silently drop the recent handoffs, which are the only ones that matter.
51	 *
52	 * A failed read returns an empty list, which counts zero handoffs and lets the
53	 * chain continue. That is the wrong direction for a safety limit, and it is
54	 * deliberate: this bounds a loop that wastes model runs, and refusing to hand off
55	 * because GitHub was briefly unreachable would stop work that is going fine. The
56	 * caller logs it so a run that could not check says so. The projection to
57	 * `ChainComment` is this caller's; the pages are the reader's.
58	 */
59	function readComments(repo: string, number: string): { comments: ChainComment[]; read: boolean } {
60	  try {
61	    return {
62	      comments: listComments(repo, number).map((comment) => ({ authorType: comment.user?.type, body: comment.body ?? "" })),
63	      read: true,
64	    };
65	  } catch {
66	    return { comments: [], read: false };
67	  }
68	}
69	
70	function main(): void {
71	  const { values } = parseArgs({
72	    args: Bun.argv.slice(2),
73	    options: {
74	      number: { type: "string" },
75	      repo: { type: "string" },
76	    },
77	  });
78	
79	  const number = values.number ?? "";
80	  const repo = values.repo ?? process.env.GITHUB_REPOSITORY ?? "";
81	  if (!number || !repo) {
82	    console.error("usage: manage_dispatch_loop.ts --number N [--repo owner/name]");
83	    process.exit(2);
84	  }
85	
86	  const limit = resolveHandoffLimit(getHandoffLimit());
87	  const noProgressLimit = resolveNoProgressLimit(getNoProgressLimit());
88	  const { comments, read } = readComments(repo, number);
89	  if (!read) console.error(`WARN could not read comments on ${repo}#${number}; treating the chain as fresh`);
90	
91	  // `isResultComment` is where the three shapes that look like a result comment from
92	  // the outside are sorted out (#354): a quotation of one, a body inside a fenced
93	  // sample, and a `waiting` ending — the run parked on work UNDER the node, which is a
94	  // decomposition progressing rather than one agent handing the node to the next. The
95	  // domain stays pure; the tag rules are composed into the reader there, which is where
96	  // the raw bodies' vocabulary lives.
97	  const handoffs = handoffsSincePerson(comments, isResultComment);
98	  // A result comment that says it changed nothing. Both halves: the result tag says it
99	  // is a result comment at all, and the changed tag says what the run did. A comment
100	  // from before this tag existed has no `changed` value and is read as something else,
101	  // which ends the walk -- old threads count zero rather than guessing.
102	  const stalled = runsWithoutChange(
103	    comments,
104	    (body) => isResultComment(body) && CHANGED_TAG.readProse(body) === "no",
105	  );
106	  const decision = stopReason({
107	    handoffs,
108	    handoffLimit: limit,
109	    runsWithoutChange: stalled,
110	    noProgressLimit,
111	  });
112	
113	  const githubOutput = process.env.GITHUB_OUTPUT;
114	  if (githubOutput) {
115	    // The limits travel with the counts, and now so does the sentence. The
116	    // escalation comment used to build its own from the handoff count whatever the
117	    // reason -- with a second limit beside it, that comment would have told a person
118	    // their chain was too long when it was not.
119	    appendFileSync(
120	      githubOutput,
121	      `auto_dispatch_count=${handoffs}\n` +
122	        `loop_limit_reached=${decision.stop}\n` +
123	        `handoff_limit=${limit}\n` +
124	        `runs_without_change=${stalled}\n` +
125	        `stop_reason=${decision.reason ?? ""}\n`,
126	    );
127	  }
128	  console.error(
129	    `Agent handoffs since a person last commented: ${handoffs}/${limit}; ` +
130	      `consecutive runs that changed nothing: ${stalled}/${noProgressLimit} (stop=${decision.stop})`,
131	  );
132	}
133	
134	if (import.meta.main) main();

